import XCTest
import UniformTypeIdentifiers
@testable import MacPad

/// MAC-50: the app's Info.plist declares every Notepad++ language's extensions
/// (generated by scripts/gen-file-types.swift).
final class FileTypesTests: XCTestCase {
    /// MAC-74: a Debug build offers to open nothing, so it never shows up in Finder's Open With.
    func testADebugBuildDeclaresNoDocumentTypes() {
        #if DEBUG
        XCTAssertNil(Bundle.main.infoDictionary?["CFBundleDocumentTypes"])
        #endif
        XCTAssertFalse(documentTypes.isEmpty, "the shipped Info.plist still declares them")
    }

    /// The shipped Info.plist: Debug builds (the test host) drop their document types (MAC-74).
    private var info: [String: Any] {
        let plist = URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("MacPad/Info.plist")
        return NSDictionary(contentsOf: plist) as? [String: Any] ?? [:]
    }
    private var documentTypes: [[String: Any]] { info["CFBundleDocumentTypes"] as? [[String: Any]] ?? [] }
    private var importedTypes: [[String: Any]] { info["UTImportedTypeDeclarations"] as? [[String: Any]] ?? [] }

    private var listedTypes: Set<String> {
        Set(documentTypes.flatMap { $0["LSItemContentTypes"] as? [String] ?? [] })
    }

    private func importedExtensions(_ declaration: [String: Any]) -> [String] {
        (declaration["UTTypeTagSpecification"] as? [String: Any])?["public.filename-extension"] as? [String] ?? []
    }

    func testEveryLanguageExtensionIsDeclared() {
        let imported = Set(importedTypes.flatMap(importedExtensions))
        let listed = listedTypes
        var missing: [String] = []
        for definition in LanguageCatalog.shared.languages.values {
            for ext in definition.extensions where !imported.contains(ext) {
                // Not imported: it must be a type macOS knows, listed by one of the document types.
                guard let type = UTType(filenameExtension: ext), listed.contains(type.identifier) else {
                    missing.append(ext)
                    continue
                }
            }
        }
        XCTAssertEqual(missing.sorted(), [], "extensions with no document type")
        XCTAssertGreaterThan(imported.count + listed.count, 200)
    }

    func testMacPadNeverTakesAFileTypeOverByBeingInstalled() {
        XCTAssertGreaterThan(documentTypes.count, 90)
        for type in documentTypes {
            XCTAssertEqual(type["CFBundleTypeRole"] as? String, "Editor", "\(type)")
            XCTAssertEqual(type["LSHandlerRank"] as? String, "Alternate", "\(type)")
        }
    }

    func testTheGenericTextTypeStaysTheFallback() {
        let text = documentTypes.first { $0["CFBundleTypeName"] as? String == "Text" }
        XCTAssertEqual(text?["LSItemContentTypes"] as? [String], ["public.text", "public.data"])
    }

    func testImportedTypesArePlainTextAndNamedLikeNotepadPlusPlus() throws {
        XCTAssertFalse(importedTypes.isEmpty)
        for declaration in importedTypes {
            let id = try XCTUnwrap(declaration["UTTypeIdentifier"] as? String)
            XCTAssertTrue(id.hasPrefix("app.macpad.lang."), id)
            XCTAssertEqual(declaration["UTTypeConformsTo"] as? [String], ["public.plain-text"])
            XCTAssertFalse(importedExtensions(declaration).isEmpty, id)
            XCTAssertTrue(listedTypes.contains(id), "\(id) has a document type")
        }
        let lua = importedTypes.first { $0["UTTypeIdentifier"] as? String == "app.macpad.lang.lua" }
        XCTAssertEqual(lua?["UTTypeDescription"] as? String, "Lua source File")
        XCTAssertEqual(lua.map(importedExtensions), ["lua"])
    }

    func testAnExtensionIsDeclaredOnce() {
        let all = importedTypes.flatMap(importedExtensions)
        XCTAssertEqual(all.count, Set(all).count)
    }

    func testCoreTypesAreUsedWhereMacOSHasThem() {
        XCTAssertTrue(listedTypes.contains("public.c-source"))
        XCTAssertTrue(listedTypes.contains("public.python-script"))
        XCTAssertTrue(listedTypes.contains("public.json"))
        XCTAssertFalse(importedTypes.flatMap(importedExtensions).contains("c"), ".c is public.c-source, not imported")
    }

    func testImportedTypesAreRegisteredOnceInstalled() throws {
        // LaunchServices registers the test host's declarations. Which type an extension resolves
        // to also depends on other installed apps (another editor may declare .lua), so the check
        // is that MacPad++'s own type is known, not that it wins.
        let lua = try XCTUnwrap(UTType("app.macpad.lang.lua"))
        XCTAssertTrue(lua.isDeclared)
        XCTAssertTrue(lua.conforms(to: .plainText))
        XCTAssertEqual(lua.tags[.filenameExtension], ["lua"])
    }
}
